WITH matched_keys AS (SELECT store_id, channel FROM orders EXCEPT ALL SELECT store_id, channel FROM orders WHERE discount < 0.18), kept_rows AS (SELECT s.* FROM orders s INNER JOIN matched_keys k ON s.store_id = k.store_id AND s.channel = k.channel) SELECT DATE_TRUNC('YEAR', order_date) AS year_start, channel, CASE WHEN discount >= 0.38 THEN 'HIGH' ELSE 'LOW' END AS discount_tier, COUNT(*) FILTER (WHERE status = 'SHIPPED') AS shipped_rows, COUNT(CASE WHEN channel = 'store' THEN 1 END) AS store_count, ROUND(SUM(discount) / NULLIF(COUNT(CASE WHEN channel = 'partner' THEN 1 END), 0), 2) AS discount_per_partner, GROUPING_ID() AS grouping_id FROM kept_rows GROUP BY ROLLUP (DATE_TRUNC('YEAR', order_date), channel, CASE WHEN discount >= 0.38 THEN 'HIGH' ELSE 'LOW' END)
